export function insideApproach(region,foot){if(!Array.isArray(foot)||foot.length!==2||!foot.every(Number.isInteger))return false;const [x,y]=foot;const row=region.rows.find(r=>r[0]===y);return !!row&&row[1].some(([a,b])=>x>=a&&x<b);}
